/**
 * The Tannery Fire — structural test generated by compile:encounter (THR-1246).
 * Expected values are baked from the content package, so this file asserts the
 * encounter's actual shape rather than any template's.
 */

import { describe, expect, it } from 'vitest';
import { TANNERY_FIRE_TEMPLATE } from '../tannery-fire';
import { expandSettings } from '../../settingClasses';
import { drawConsequenceHand, handAfterSwap } from '../../content-eval/consequenceDraw';

describe("The Tannery Fire — template structure", () => {
  it('carries its identity', () => {
    expect(TANNERY_FIRE_TEMPLATE.id).toBe('encounter.town.tannery_fire');
    expect(TANNERY_FIRE_TEMPLATE.reach).toBe('iron');
    expect(TANNERY_FIRE_TEMPLATE.rarityTier).toBe(2);
    expect(TANNERY_FIRE_TEMPLATE.steps).toHaveLength(2);
  });

  it('step 0 deals the authored hand', () => {
    const step = TANNERY_FIRE_TEMPLATE.steps[0];
    if (!('narrativeTemplate' in step)) throw new Error('expected a plain step');
    expect((step.nudges ?? []).map(nudge => nudge.id)).toEqual(['tannery.still_the_wind', 'tannery.steady_the_line']);
    const spheres = [...new Set((step.nudges ?? []).map(nudge => nudge.sphere).filter(Boolean))].sort();
    expect(spheres).toEqual(['mind', 'order']);
  });

  it('step 1 deals the authored hand', () => {
    const step = TANNERY_FIRE_TEMPLATE.steps[1];
    if (!('narrativeTemplate' in step)) throw new Error('expected a plain step');
    expect((step.nudges ?? []).map(nudge => nudge.id)).toEqual(['tannery.crack_the_timbers', 'tannery.show_the_danger']);
    const spheres = [...new Set((step.nudges ?? []).map(nudge => nudge.sphere).filter(Boolean))].sort();
    expect(spheres).toEqual(['entropy', 'light']);
  });
  it('derives its location subtypes from the declared envelope', () => {
    expect(TANNERY_FIRE_TEMPLATE.settings).toEqual(['urban']);
    expect(TANNERY_FIRE_TEMPLATE.locationSubtypes).toEqual(expandSettings(['urban']));
  });

  it('records exactly the hand its id draws (binding, THR-1145)', () => {
    expect(TANNERY_FIRE_TEMPLATE.consequenceDraw).toEqual(['standing', 'place']);
    expect(TANNERY_FIRE_TEMPLATE.consequenceDraw).toEqual(
      handAfterSwap(
        drawConsequenceHand({
          templateId: 'encounter.town.tannery_fire',
          reach: 'iron',
          rarityTier: 2,
        }),
        TANNERY_FIRE_TEMPLATE.consequenceSwap,
      ),
    );
  });
});
